  <script>
    const input=document.getElementById('search'),empty=document.getElementById('empty');input.addEventListener('input',()=>{const q=input.value.trim().toLowerCase();let total=0;document.querySelectorAll('[data-category]').forEach(section=>{let count=0;section.querySelectorAll('[data-tool]').forEach(tool=>{const show=!q||tool.dataset.search.includes(q);tool.style.display=show?'grid':'none';if(show)count++});section.style.display=count?'block':'none';section.querySelector('[data-visible]').textContent=count;total+=count});empty.style.display=total?'none':'block'});
    const menuToggle=document.querySelector('.menu-toggle'),primaryNav=document.querySelector('.primary-nav');menuToggle?.addEventListener('click',function(){const open=this.getAttribute('aria-expanded')==='true';this.setAttribute('aria-expanded',String(!open));primaryNav.classList.toggle('is-open',!open)});document.querySelector('.nav-search')?.addEventListener('click',()=>{input.focus();input.scrollIntoView({behavior:'smooth',block:'center'})});document.querySelectorAll('.nav-dropdown>button').forEach(button=>button.addEventListener('click',function(event){event.stopPropagation();const item=this.parentElement;document.querySelectorAll('.nav-dropdown.is-open').forEach(open=>{if(open!==item)open.classList.remove('is-open')});item.classList.toggle('is-open');this.setAttribute('aria-expanded',String(item.classList.contains('is-open')))}));document.addEventListener('click',()=>document.querySelectorAll('.nav-dropdown.is-open').forEach(item=>item.classList.remove('is-open')));const themeButton=document.querySelector('.theme-switch'),savedTheme=localStorage.getItem('fxn-theme');if(savedTheme==='dark')document.body.classList.add('home-dark');themeButton?.addEventListener('click',function(){document.body.classList.toggle('home-dark');localStorage.setItem('fxn-theme',document.body.classList.contains('home-dark')?'dark':'light');this.textContent=document.body.classList.contains('home-dark')?'☀':'☾'});
  </script>
